using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "TimelessAction", menuName = "Data/Battle/Battle Actions/Tactical Actions/Timeless Action")]
public class TimelessAction : ChooseDiceAction
{
	[SerializeField]
	private BattleAction secondAction;

	[SerializeField]
	private int secondActionValue;

	[SerializeField]
	private OmenLogic secondOmenLogic;

	public BattleAction SecondAction => secondAction;

	public int SecondActionValue => secondActionValue;

	public override bool CheckConditionToBeCasted(bool playerHand, DiceOwnerEnum diceOwnerEnum)
	{
		if (playerHand)
		{
			if (ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInHandAmount() > 1)
			{
				return ReferenceSingleton<PlayerDiceHandHolder>.Instance.IsAtLeastTwoNonMustUseDice();
			}
			return false;
		}
		if (ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInHandAmount() > 0)
		{
			return ReferenceSingleton<PlayerDiceHandHolder>.Instance.IsAnyNonMustUseDice();
		}
		return false;
	}

	public override bool CheckCondition(DiceInstance diceInstance)
	{
		return !diceInstance.ActionFace.BattleAction.BaseBattleActionData.HasMandatoryBattleActionInteractionEnum();
	}

	public override void Cast(GameObject source)
	{
		if (diceList.Count == 0)
		{
			for (int i = 0; i < ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInHandAmount(); i++)
			{
				diceList.Add(ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInstanceFromHand(i));
			}
			DefaultCast(goBackToDiceTray: false, source);
		}
		else
		{
			DefaultCast(goBackToDiceTray: true, source);
		}
	}

	protected virtual void DefaultCast(bool goBackToDiceTray, GameObject source)
	{
		for (int i = 0; i < diceList.Count; i++)
		{
			DiceInstance diceInstance = diceList[i];
			diceInstance.SetDisableDiscard(value: true);
			if (IsVFXEnabled())
			{
				GetVFX(4f).GetComponent<ParticleFollower>().Initialize(diceInstance);
			}
			SetDiceInstanceGoBackToOriginalPositionAnimation(goBackToDiceTray, i, diceInstance);
		}
		SpawnSecondVFXOnPlayerPosition(3f);
		if (IsVFXEnabled())
		{
			PlaySFX();
		}
		secondOmenLogic.ActivateOmen(secondAction, secondActionValue, null, source);
		EndAction(goBackToDiceTray);
		ResetVariables();
	}
}
